WITH matched_keys AS (SELECT merchant, id FROM transactions EXCEPT SELECT merchant, id FROM transactions WHERE is_flagged = FALSE), verified AS (SELECT s.* FROM transactions s INNER JOIN matched_keys k ON s.merchant = k.merchant AND s.id = k.id) SELECT account_id, DATE_TRUNC('QUARTER', txn_time) AS quarter_start, AVG(amount) AS avg_amount, (UNIX_TIMESTAMP(MAX(txn_time)) - UNIX_TIMESTAMP(MIN(txn_time))) / 60 AS span_minutes, (UNIX_TIMESTAMP(MAX(txn_time)) - UNIX_TIMESTAMP(MIN(txn_time))) / 60 AS duration_min, MAX(amount) FILTER (WHERE txn_type = 'FEE') AS fee_max_amount, PERCENTILE_APPROX(amount, ARRAY(0.25, 0.5, 0.75)) AS amount_quartiles FROM verified GROUP BY CUBE (account_id, DATE_TRUNC('QUARTER', txn_time)) ORDER BY account_id;
